const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

async function main() {
  // 1. lazy open: stream() alone does not open
  {
    let opens = 0, closes = 0;
    const service = new EventService({
      open: async () => { opens++; return { read: async () => null, close: async () => { closes++; } }; }
    });
    const gen = service.stream();
    assert.equal(opens, 0);
    // returning unopened generator does not open or close
    const r = await gen.return();
    assert.deepEqual(r, { value: undefined, done: true });
    assert.equal(opens, 0);
    assert.equal(closes, 0);
  }

  // 2. normal exhaustion: yields mapped in order, one close, no read-ahead
  {
    let reads = 0, closes = 0, opens = 0;
    const values = ['a', 'b', null];
    const service = new EventService({
      open: async () => { opens++; return {
        read: async () => { reads++; return values.length ? values.shift() : null; },
        close: async () => { closes++; }
      }; }
    });
    const gen = service.stream();
    assert.equal(opens, 0);
    const seen = [];
    for await (const v of gen) seen.push(v);
    assert.deepEqual(seen, ['A', 'B']);
    assert.equal(opens, 1);
    assert.equal(reads, 3);
    assert.equal(closes, 1);
  }
  ...
}
```

